# owner: platform
"""Absence notices for parents and guardians."""

from datetime import date
from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

def _check_marks_belong(
    student: Student, marks: List[Mark]
) -> None:
    for mark in marks:
        other = mark.student_id
        if other != student.student_id:
            raise ValueError(f"mark for {other}")

def _missed_days(
    student: Student, marks: List[Mark]
) -> List[date]:
    _check_marks_belong(student, marks)
    missed = days_missed(marks)
    if not missed:
        raise ValueError("no absences to write about")
    return missed

def _format_day(when: date) -> str:
    return f"{when:%B} {when.day}, {when.year}"

def _absence_phrase(missed: List[date]) -> str:
    noun = "day" if len(missed) == 1 else "days"
    dates = "; ".join(_format_day(when) for when in missed)
    return f"was absent {len(missed)} {noun}: {dates}."

# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice text listing each absent day."""
    missed = _missed_days(student, list(marks))
    name = f"{student.first_name} {student.last_name}"
    phrase = _absence_phrase(missed)
    return f"Dear parent or guardian, {name} {phrase}"
